    if (co) $('concprompt').textContent = 'This plan was saved with a concentration only (' + C.fmt(co.concValue, 4) + ' ' + co.concUnit + '/mL). It keeps working as entered. Optionally choose the vial strength, unit and water added to record how the vial is mixed; leave all three empty to keep the entered concentration.';
    const ct = C.concText(pres), out = $('concout'), prev = clear($('drawpreview'));
    let err = null; try { C.concentration(pres); } catch (x) { err = x.message; }
    out.className = 'concout' + (err ? ' empty' : '');
