    if (!currentCompound() && !$('customname').value.trim()) { box.append(h('p', { class: 'err', text: 'Enter a compound name.' })); btn.disabled = true; return; }
    let plan; try { plan = buildPlan(); } catch (x) { box.append(h('p', { class: 'err', text: x.message })); btn.disabled = true; return; }
    const v = C.validatePlan(plan);
    if (!v.ok) { box.append(h('ul', { class: 'err', id: 'reviewerrors' }, v.errors.map(e => h('li', { text: e })))); btn.disabled = true; return; }
    const occ = C.allOccurrences(plan);
    box.append(h('p', { id: 'reviewsummary', text: occ.length + ' scheduled doses from ' + occ[0].scheduledDate + ' to ' + occ[occ.length - 1].scheduledDate + ' (' + C.describeRecurrence(plan.recurrence) + '). ' + (plan.syringe.type !== 'none' ? 'Every dose was checked against the ' + plan.syringe.capacityMl + ' mL syringe capacity.' : 'No syringe/draw math applies to this presentation.') }));
