    const rows = occ.map((o, i) => h('tr', null, h('td', { text: String(i + 1) }), h('td', { text: o.scheduledDate }), h('td', { text: 'Step ' + (o.stepIndex + 1) + (o.continuation ? ' (cont.)' : '') }), h('td', null, doseNodes(o, plan))));
