    if (C.PRESENTATIONS[pr.type].math) { $('syringe').value = p.syringe.type; $('capwrap').classList.toggle('hidden', p.syringe.type === 'none'); if (p.syringe.capacityMl) $('capacity').value = String(p.syringe.capacityMl); }
